{
  "explanation": "A secant line cuts through two points on a curve: a fixed point P at x = a and a nearby point Q at x = a + h. As h shrinks toward zero, Q slides toward P and the secant rotates into a limiting position—the tangent line. The slope of that tangent is the derivative f'(a), the instantaneous rate of change at a.",
  "manimCode": "const ax = new Axes({
  xRange: [-1.5, 4, 1],
  yRange: [-0.5, 3.5, 1],
  xLength: 9,
  yLength: 5,
  tips: true
});
ax.shift(scaleVec(0.3, DOWN));

const f = (x) => 0.25 * x * x;
const df = (x) => 0.5 * x;
const a = 1.0;
let h = 2.0;

const curve = ax.plot(f, { color: BLUE, xRange: [-1.5, 3.8], numSamples: 300 });

// Fixed tangent line (faint) so the limit is visible
const mT = df(a);
const tangent = new Line({
  start: ax.c2p(-1.2, f(a) + mT * (-1.2 - a)),
  end: ax.c2p(3.8, f(a) + mT * (3.8 - a)),
  color: RED
});
tangent.setOpacity(0.35).setStrokeWidth(3);

function makeSecant(hVal) {
  const y1 = f(a);
  const y2 = f(a + hVal);
  const m = Math.abs(hVal) < 1e-9 ? df(a) : (y2 - y1) / hVal;
  const line = new Line({
    start: ax.c2p(-1.2, y1 + m * (-1.2 - a)),
    end: ax.c2p(3.8, y1 + m * (3.8 - a)),
    color: GREEN
  });
  line.setStrokeWidth(3);
  return line;
}

let secant = makeSecant(h);

const dotP = new Dot({ point: ax.c2p(a, f(a)), color: YELLOW });
let dotQ = new Dot({ point: ax.c2p(a + h, f(a + h)), color: ORANGE });

// Drop lines to the x-axis to emphasize h
const dropP = new Line({ start: ax.c2p(a, 0), end: ax.c2p(a, f(a)), color: GRAY });
dropP.setOpacity(0.45).setStrokeWidth(1.5);
let dropQ = new Line({ start: ax.c2p(a + h, 0), end: ax.c2p(a + h, f(a + h)), color: GRAY });
dropQ.setOpacity(0.45).setStrokeWidth(1.5);

let hSeg = new Line({ start: ax.c2p(a, 0), end: ax.c2p(a + h, 0), color: WHITE });
hSeg.setStrokeWidth(2);

const title = new MathTex({ latex: '\\lim_{h \\to 0} \\frac{f(a+h)-f(a)}{h} = f\'(a)' });
await title.waitForRender();
title.scale(0.75);
title.moveTo([0, 3.4, 0]);

const pLab = new Text({ text: 'P', fontSize: 22, color: YELLOW });
pLab.nextTo(dotP, DL);
pLab.shift(scaleVec(0.15, LEFT));

let qLab = new Text({ text: 'Q', fontSize: 22, color: ORANGE });
qLab.nextTo(dotQ, UR);

let hLab = new Text({ text: 'h = 2.00', fontSize: 22, color: WHITE });
hLab.moveTo(ax.c2p(a + h / 2, -0.35));

let slopeLab = new Text({
  text: 'secant slope ≈ ' + ((f(a + h) - f(a)) / h).toFixed(3),
  fontSize: 22,
  color: GREEN
});
slopeLab.moveTo([0, -3.3, 0]);

const tanLab = new Text({ text: 'tangent', fontSize: 18, color: RED });
tanLab.moveTo(ax.c2p(3.2, f(a) + mT * (3.2 - a)));
tanLab.shift(scaleVec(0.35, UP));

scene.add(ax, curve, tangent, secant, dropP, dropQ, hSeg, dotP, dotQ, title, pLab, qLab, hLab, slopeLab, tanLab);

function refresh(val) {
  h = val;
  scene.remove(secant, dotQ, dropQ, hSeg, qLab, hLab, slopeLab);

  secant = makeSecant(h);
  dotQ = new Dot({ point: ax.c2p(a + h, f(a + h)), color: ORANGE });
  dropQ = new Line({ start: ax.c2p(a + h, 0), end: ax.c2p(a + h, f(a + h)), color: GRAY });
  dropQ.setOpacity(0.45).setStrokeWidth(1.5);
  hSeg = new Line({ start: ax.c2p(a, 0), end: ax.c2p(a + h, 0), color: WHITE });
  hSeg.setStrokeWidth(2);

  qLab = new Text({ text: 'Q', fontSize: 22, color: ORANGE });
  qLab.nextTo(dotQ, UR);

  hLab = new Text({ text: 'h = ' + h.toFixed(2), fontSize: 22, color: WHITE });
  hLab.moveTo(ax.c2p(a + h / 2, -0.35));

  const m = (f(a + h) - f(a)) / h;
  slopeLab = new Text({
    text: 'secant slope ≈ ' + m.toFixed(3) + '   →   f\'(a) = ' + df(a).toFixed(3),
    fontSize: 22,
    color: GREEN
  });
  slopeLab.moveTo([0, -3.3, 0]);

  scene.add(secant, dropQ, hSeg, dotQ, qLab, hLab, slopeLab);
}

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({
  label: 'h → 0',
  min: 0.02,
  max: 2.5,
  value: 2.0,
  step: 0.01,
  onChange: (val) => refresh(val)
});
controls.addButton({
  label: 'Reset h',
  onClick: () => refresh(2.0)
});

makeHoverable(dotP, scene, { hoverScale: 1.3, hoverColor: WHITE });
makeHoverable(dotQ, scene, { hoverScale: 1.3, hoverColor: WHITE });

await scene.wait(999999);"
}

